import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-10-12","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-10-12","date":"2021-10-12T00:00:00.000Z","updated":"2021-10-13T00:00:00.000Z","tags":["Ceph Orchestrator","Cephadm","Container Registry Management","Manila Integration","Ganesha Interaction"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-12.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-10-12.md","lastUpdated":1780459816000}'),i={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-10-12.md"};function n(o,e,s,h,p,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<p>本次Ceph Orchestrator会议主要围绕Ceph Orchestrator的多个议题展开讨论，包括Cephadm集成、容器注册表管理、Manila与Ceph及Ganesha的交互等。</p><ol><li><p><strong>Cephadm集成</strong></p><ul><li>冬季项目已启动，Cephadm新增了新的集成功能。</li><li>已有两名学生加入项目，并期待更多功能集成到视频演示中。</li></ul></li><li><p><strong>容器注册表管理</strong></p><ul><li>讨论了如何处理容器注册表版本列表，特别是自定义注册表与上游注册表的差异。</li><li>探讨了使用Python库与Docker注册表交互的可行性，但存在维护问题。</li><li>讨论了是否需要列出所有标签，以及如何处理最新标签的更新。</li></ul></li><li><p><strong>Manila与Ceph及Ganesha的交互</strong></p><ul><li>讨论了Manila如何通过Orchestrator与Ceph及Ganesha交互，特别是通过CLI还是API。</li><li>探讨了权限问题，特别是非管理员用户如何执行CLI命令。</li><li>讨论了如何更新Ganesha配置文件的部分内容，以及如何获取当前Ganesha demon的状态描述。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续探索Cephadm的新集成功能，并鼓励更多学生参与。</li><li>确定使用CLI作为与Orchestrator交互的主要方式，尽管也考虑了API的可能性。</li><li>确认了非管理员用户执行CLI命令所需的权限，并计划进一步细化这些权限。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续开发和测试Cephadm的新集成功能。</li><li>进一步研究如何通过CLI或API与Orchestrator进行更有效的交互。</li><li>细化非管理员用户的权限设置，确保Manila能够安全地与Ceph及Ganesha交互。</li><li>探索如何更好地管理和更新Ganesha配置文件，以及如何获取和展示Ganesha demon的当前状态。</li></ul><h4 id="其他讨论点" tabindex="-1">其他讨论点 <a class="header-anchor" href="#其他讨论点" aria-label="Permalink to &quot;其他讨论点&quot;">​</a></h4><ul><li>讨论了Ingress demon的状态和其在生产环境中的适用性。</li><li>探讨了如何处理Orchestrator命令的异步性质，以及如何确保数据路径的连续性。</li></ul><p>本次会议对Ceph Orchestrator的未来发展方向提供了清晰的指引，并确定了后续的工作重点。</p>',9)])])}const C=a(i,[["render",n]]);export{_ as __pageData,C as default};
